<template>
  <div class="fb-lo-overview">
    <div class="page-head">
      <div class="page-intro">
        <h3 class="fb-title page-intro__title">
          {{ $t('layouts_and_selection_rules') }}
          <q-tooltip anchor="top middle" self="bottom middle" :offset="[0, 6]">
            {{ $t('layouts_and_selection_rules') }}
          </q-tooltip>
        </h3>
        <p class="page-intro__subtitle page-intro__subtitle--sm">
          {{ $t('layouts_overview_subtitle') }}
        </p>
      </div>

      <div class="fb-lo-screentabs" role="tablist" :aria-label="$t('screen')">
        <button
          v-for="screen in screens"
          :key="screen.value"
          type="button"
          role="tab"
          class="fb-lo-screentab"
          :class="{ 'fb-lo-screentab--active': activeScreen === screen.value }"
          :aria-selected="activeScreen === screen.value"
          @click="activeScreen = screen.value"
        >
          {{ screen.label }}
          <span v-if="counts[screen.value] !== null" class="fb-lo-screentab__count">
            {{ counts[screen.value] }}
          </span>
        </button>
      </div>
    </div>

    <div class="fb-lo-ctxbar">
      <div v-if="docType" class="page-doctype">
        <Icon icon="mdi:file-document-outline" class="page-doctype__icon" />
        <span class="page-doctype__label">{{ $t('document_type') }}</span>
        <span class="page-doctype__value" data-test="doc-type">{{ docType }}</span>
      </div>

      <div class="fb-lo-tabs" role="tablist" :aria-label="$t('layout_type')">
        <button
          v-for="tab in layoutTabs"
          :key="tab.value"
          type="button"
          role="tab"
          class="fb-lo-tab"
          :class="{ 'fb-lo-tab--active': activeLayoutType === tab.value }"
          :aria-selected="activeLayoutType === tab.value"
          @click="activeLayoutType = tab.value"
        >
          {{ tab.label }}
        </button>
      </div>
    </div>

    <LayoutsPanel
      v-show="activeScreen === 'layouts'"
      :doc-type="docType"
      :layout-type="activeLayoutType"
      :active="activeScreen === 'layouts'"
      @update:count="counts.layouts = $event"
    />
    <SelectionRulesPanel
      v-show="activeScreen === 'rules'"
      :doc-type="docType"
      :layout-type="activeLayoutType"
      :active="activeScreen === 'rules'"
      @update:count="counts.rules = $event"
    />
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { layout_types } from 'src/constants';
import LayoutsPanel from 'src/formBuilder/components/LayoutsPanel.vue';
import SelectionRulesPanel from 'src/formBuilder/components/SelectionRulesPanel.vue';

const LAYOUT_TYPE = layout_types.field_validation;

type ScreenKey = 'layouts' | 'rules';

export default defineComponent({
  name: 'LayoutsOverview',
  components: { LayoutsPanel, SelectionRulesPanel },
  data() {
    return {
      docType: '',
      activeScreen: 'layouts' as ScreenKey,
      activeLayoutType: LAYOUT_TYPE,
      screens: [
        { label: this.$t('layouts'), value: 'layouts' as ScreenKey },
        { label: this.$t('selection_rules'), value: 'rules' as ScreenKey },
      ],
      counts: { layouts: null, rules: null } as Record<ScreenKey, number | null>,
      layoutTabs: [
        { label: this.$t('field_validation'), value: layout_types.field_validation },
        { label: this.$t('approval'), value: layout_types.approval },
        { label: this.$t('reject'), value: layout_types.reject },
        { label: this.$t('review'), value: layout_types.review },
      ],
    };
  },
  watch: {
    '$route.params.doc_type'(val: string) {
      this.docType = val || '';
      this.clearHiddenCount();
    },
    activeScreen() {
      this.clearHiddenCount();
    },
    activeLayoutType() {
      this.clearHiddenCount();
    },
  },
  created() {
    this.docType = (this.$route.params.doc_type as string) || '';
    // Returning from the selection-rule editor (its own route) restores the tab
    // the user left from, so Cancel/Save lands back where they were.
    const screen = this.$route.query.screen as ScreenKey | undefined;
    if (screen === 'layouts' || screen === 'rules') {
      this.activeScreen = screen;
    }
    const layoutType = this.$route.query.layout_type as string | undefined;
    if (layoutType && this.layoutTabs.some((tab: { value: string }) => tab.value === layoutType)) {
      this.activeLayoutType = layoutType;
    }
  },
  methods: {
    // The hidden screen would otherwise keep the previous tab's number. Its
    // panel re-emits the count when it activates.
    clearHiddenCount() {
      this.counts[this.activeScreen === 'layouts' ? 'rules' : 'layouts'] = null;
    },
  },
});
</script>

