<template>
  <div class="fb-lo-panel">
    <!-- Toolbar: search + scope filter (left), New layout (right) -->
    <div class="fb-lo-toolbar">
      <div class="fb-lo-toolbar__left">
        <div class="fb-lo-search">
          <Icon icon="mdi:magnify" class="fb-lo-search__icon" />
          <input
            v-model="searchQuery"
            type="text"
            :placeholder="$t('search_layouts_placeholder')"
            :aria-label="$t('search_layouts')"
          />
        </div>
        <div class="fb-lo-seg">
          <button
            v-for="scope in scopeFilters"
            :key="scope.value"
            type="button"
            class="fb-lo-seg__btn"
            :class="{ 'fb-lo-seg__btn--active': scopeFilter === scope.value }"
            @click="scopeFilter = scope.value"
          >
            {{ scope.label }}
          </button>
        </div>
      </div>
      <div class="fb-lo-toolbar__right">
        <f-btn :label="$t('new_layout')" icon="add" @click="openNewLayoutDialog" />
      </div>
    </div>

    <!-- Loading skeletons -->
    <div v-if="isLoading" class="fb-lo-grid" aria-busy="true">
      <div
        v-for="n in 6"
        :key="n"
        class="fb-lo-card fb-lo-card--skeleton"
      >
        <div class="fb-lo-preview" aria-hidden="true">
          <div
            v-for="(row, i) in previewRows"
            :key="i"
            class="fb-lo-preview__row"
          >
            <span
              v-for="(w, j) in row"
              :key="j"
              class="fb-lo-preview__bar"
              :style="{ flexBasis: w }"
            />
          </div>
        </div>
        <span class="fb-lo-sk-line fb-lo-sk-line--title" />
        <div class="fb-lo-sk-badges">
          <span class="fb-lo-sk-pill" />
          <span class="fb-lo-sk-pill" />
        </div>
      </div>
    </div>

    <!-- Empty state -->
    <div v-else-if="filteredLayouts.length === 0" class="fb-lo-empty">
      <Icon icon="mdi:view-grid-plus-outline" class="fb-lo-empty__icon" />
      <p class="fb-lo-empty__title">
        {{ hasQueryOrFilter ? $t('no_matching_layouts') : $t('no_layouts_yet') }}
      </p>
      <p class="fb-lo-empty__hint">
        {{
          hasQueryOrFilter
            ? $t('try_different_search_or_filter')
            : $t('layouts_empty_hint')
        }}
      </p>
      <f-btn v-if="!hasQueryOrFilter" :label="$t('new_layout')" icon="add" @click="openNewLayoutDialog" />
    </div>

    <!-- Layout cards -->
    <div v-else class="fb-lo-grid">
      <article
        v-for="layout in filteredLayouts"
        :key="layout.id"
        class="fb-lo-card"
        @click="editLayout(layout)"
      >
        <div class="item-name ellipsis">
          {{ layout.title }}
          <q-tooltip anchor="top middle" self="bottom middle" :offset="[0, 6]">
            {{ layout.title }}
          </q-tooltip>
        </div>

        <!-- Badges -->
        <div class="fb-lo-badges">
          <!-- <q-badge color="grey" :label="layoutTypeLabel(layout)" /> -->
          <q-badge
            :color="isDefault(layout) ? 'orange' : 'primary'"
            :label="isDefault(layout) ? $t('system_default') : $t('custom')"
          />
        </div>

        <!-- Metadata -->
        <!-- <div class="fb-lo-meta">
          <span class="fb-lo-meta__item">
            <span class="fb-lo-meta__label">{{ $t('type') }}</span>
            <span class="fb-lo-meta__value">{{ layout.doc_type_key }}</span>
          </span>
          <span class="fb-lo-meta__item">
            <span class="fb-lo-meta__label">{{ $t('origin') }}</span>
            <span class="fb-lo-meta__value">{{ originLabel(layout) }}</span>
          </span>
        </div> -->

        <div class="fb-lo-edited">
          <span class="fb-lo-meta__label">{{ $t('edited') }}</span>
          <span class="fb-lo-meta__value">{{ editedLabel(layout) }}</span>
        </div>

        <!-- Divider + footer: rule-target count on the left, actions on the right -->
        <div class="fb-lo-footer" @click.stop>
          <div class="fb-lo-footer__meta">
            <Icon icon="mdi:sort-variant" class="fb-lo-footer__icon" />
            <span>{{ ruleCountLabel(layout) }}</span>
          </div>
          <div class="fb-lo-footer__actions">
            <button type="button" class="fb-lo-action" @click="editLayout(layout)">
              {{ isDefault(layout) ? $t('view') : $t('edit') }}
            </button>
            <button
              type="button"
              class="fb-lo-action"
              :disabled="busyId === layout.id"
              @click="openCloneDialog(layout)"
            >
              {{ $t('clone') }}
            </button>
            <button
              v-if="!isDefault(layout)"
              type="button"
              class="fb-lo-action fb-lo-action--danger"
              :disabled="busyId === layout.id"
              @click="confirmDelete(layout)"
            >
              {{ $t('delete') }}
            </button>
          </div>
        </div>
      </article>
    </div>

    <ConfirmDialog
      v-model="showDeleteConfirm"
      :message="deleteMessage"
      :confirm-label="$t('delete')"
      :cancel-label="$t('cancel')"
      confirm-color="negative"
      @confirm="deleteLayout"
    />

    <!-- Clone dialog: rename the copy before creating it. ESC-closeable
         (non-persistent). "Close" dismisses; "Clone" calls the API. -->
    <q-dialog v-model="showCloneDialog">
      <q-card style="min-width: 420px">
        <q-card-section class="bg-primary text-white q-py-sm q-px-md">
          <div class="row items-center">
            <q-icon name="content_copy" size="xs" color="white" class="q-mr-sm" />
            <div class="text-subtitle1">{{ $t('clone_layout') }}</div>
          </div>
        </q-card-section>
        <q-card-section class="q-pt-md">
          <q-input
            v-model="cloneTitle"
            outlined
            dense
            autofocus
            :label="$t('layout_name')"
            :disable="cloneBusy"
            @keyup.enter="confirmClone"
          />
        </q-card-section>
        <q-card-actions align="right" class="q-pa-md">
          <f-btn appearance="cancel" :label="$t('close')" :disable="cloneBusy" v-close-popup />
          <f-btn
            :label="$t('clone')"
            :loading="cloneBusy"
            :disable="!cloneTitle.trim()"
            @click="confirmClone"
          />
        </q-card-actions>
      </q-card>
    </q-dialog>

    <!-- New-layout dialog: name the layout, then create it and open the
         builder on the new id. Persistent — it stays put until the layout is
         created or the user explicitly closes it, so a failed create keeps the
         typed title for a retry (the error surfaces in a toast). -->
    <q-dialog v-model="showNewLayoutDialog" persistent>
      <q-card style="min-width: 420px">
        <q-card-section class="bg-primary text-white q-py-sm q-px-md">
          <div class="row items-center">
            <q-icon name="add" size="xs" color="white" class="q-mr-sm" />
            <div class="text-subtitle1">{{ $t('new_layout') }}</div>
          </div>
        </q-card-section>
        <q-card-section class="q-pt-md">
          <q-input
            v-model="newLayoutTitle"
            outlined
            dense
            autofocus
            :label="$t('layout_name')"
            :disable="newLayoutBusy"
            @keyup.enter="confirmNewLayout"
          />
        </q-card-section>
        <q-card-actions align="right" class="q-pa-md">
          <f-btn
            appearance="cancel"
            :label="$t('close')"
            :disable="newLayoutBusy"
            v-close-popup
          />
          <f-btn
            :label="$t('create')"
            :loading="newLayoutBusy"
            :disable="!newLayoutTitle.trim()"
            @click="confirmNewLayout"
          />
        </q-card-actions>
      </q-card>
    </q-dialog>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { formBuilderApiService } from 'src/services';
import { ApiExceptions } from 'src/exceptions/index';
import { notify } from 'src/components/notifications/notify';
import { isDefaultOrg, layout_types } from 'src/constants';
import ConfirmDialog from 'src/supplier/pages/ConfirmDialog.vue';
import { formBuilderRouter } from 'src/formBuilder/utils/formBuilderRouter';

const LAYOUT_TYPE = layout_types.field_validation;

export interface LayoutTemplate {
  id: string;
  // The sentinel default org owns the system layouts — see isDefault below.
  org_id: string;
  doc_type_key: string;
  sub_doc_type_key: string | null;
  title: string;
  doc_origin: string;
  layout_type: string;
  // Optional — populated by the backend when available; UI degrades gracefully otherwise.
  last_modified_on?: string;
  created_on?: string;
  rule_count?: number;
}

export default defineComponent({
  name: 'LayoutsPanel',
  components: { ConfirmDialog },
  props: {
    docType: { type: String, default: '' },
    layoutType: { type: String, default: LAYOUT_TYPE },
    // False while the sibling tab is showing: this panel stays mounted (v-show),
    // so without this it would fetch a list nobody is looking at.
    active: { type: Boolean, default: true },
  },
  emits: ['update:count'],
  data() {
    return {
      layouts: [] as LayoutTemplate[],
      isLoading: false,
      // The doc type + layout type the loaded list belongs to; '' = nothing loaded.
      loadedKey: '',
      busyId: '',
      showDeleteConfirm: false,
      pendingDelete: null as LayoutTemplate | null,
      // Clone dialog state.
      showCloneDialog: false,
      pendingClone: null as LayoutTemplate | null,
      cloneTitle: '',
      cloneBusy: false,
      // New-layout dialog state.
      showNewLayoutDialog: false,
      newLayoutTitle: '',
      newLayoutBusy: false,
      searchQuery: '',
      scopeFilter: 'all' as 'all' | 'my' | 'system',
      // Decorative preview bars (widths per row) — the loading skeleton.
      previewRows: [
        ['52%', '30%'],
        ['58%', '30%'],
        ['26%', '46%'],
        ['46%', '30%'],
      ],
    };
  },
  computed: {
    // Computed, not data: built in data() the labels would keep the language
    // that was active when the panel mounted.
    scopeFilters(): { label: string; value: 'all' | 'my' | 'system' }[] {
      return [
        { label: this.$t('all'), value: 'all' },
        { label: this.$t('my_layouts'), value: 'my' },
        { label: this.$t('system_label'), value: 'system' },
      ];
    },
    // Identifies the list currently on screen; a change means a refetch.
    listKey(): string {
      return `${this.docType}|${this.layoutType}`;
    },
    deleteMessage(): string {
      const name = this.pendingDelete?.title || this.$t('this_layout');
      return this.$t('delete_item_confirm', { name });
    },
    hasQueryOrFilter(): boolean {
      return this.searchQuery.trim() !== '' || this.scopeFilter !== 'all';
    },
    // field_validation stays typeless in the URL so main.vue enters
    // field-validation mode; other types carry their layout_type segment.
    routeLayoutType(): string {
      return this.layoutType === LAYOUT_TYPE ? '' : this.layoutType;
    },
    filteredLayouts(): LayoutTemplate[] {
      const q = this.searchQuery.trim().toLowerCase();
      return this.layouts.filter((l) => {
        if (this.scopeFilter === 'system' && !this.isDefault(l)) return false;
        if (this.scopeFilter === 'my' && this.isDefault(l)) return false;
        if (q) {
          const haystack = `${l.title} ${l.doc_origin} ${l.doc_type_key}`.toLowerCase();
          if (!haystack.includes(q)) return false;
        }
        return true;
      });
    },
  },
  watch: {
    docType() {
      this.loadIfNeeded();
    },
    layoutType() {
      // A new layout-type tab starts clean.
      this.searchQuery = '';
      this.scopeFilter = 'all';
      this.loadIfNeeded();
    },
    active() {
      this.loadIfNeeded();
    },
  },
  mounted() {
    this.loadIfNeeded();
  },
  methods: {
    // Fetch only what is both visible and out of date. Coming back to a tab
    // whose list is still current just re-announces the count.
    loadIfNeeded() {
      if (!this.active) return;
      if (this.loadedKey && this.loadedKey === this.listKey) {
        this.$emit('update:count', this.layouts.length);
        return;
      }
      this.loadLayouts();
    },
    async loadLayouts() {
      if (!this.docType) {
        // Drop the stale cards; leaving them would let the user open a layout
        // belonging to a doc type that is no longer selected.
        this.layouts = [];
        this.loadedKey = '';
        this.$emit('update:count', 0);
        return;
      }

      // Captured up front: a tab or doc-type switch mid-flight makes this
      // response stale, and applying it would show the wrong list.
      const key = this.listKey;
      this.isLoading = true;
      try {
        const response: any = await formBuilderApiService.getAllLayoutTemplates({
          layout_type: this.layoutType,
          doc_type: this.docType,
          // Every scope, so the org's own layouts and the system defaults both
          // arrive — isDefault tells them apart for the badge and the filter.
          scope: 'all',
        });
        if (key !== this.listKey) return;

        // Service returns the envelope { success, data }, but tolerate a bare array too.
        this.layouts = Array.isArray(response)
          ? response
          : Array.isArray(response?.data)
            ? response.data
            : [];
        this.loadedKey = key;
        this.$emit('update:count', this.layouts.length);
      } catch (err) {
        if (key !== this.listKey) return;
        notify.error(ApiExceptions.getErrorMessage(err as dynamicObj));
        logError(err);
      } finally {
        // The superseding load owns the flag from here on.
        if (key === this.listKey) this.isLoading = false;
      }
    },
    // System layouts are the ones owned by the sentinel default org — not the
    // ones whose origin happens to be called DEFAULT. isDefaultOrg is the same
    // check ScriptCard and List-of-Values use.
    isDefault(layout: LayoutTemplate): boolean {
      return isDefaultOrg(layout.org_id);
    },
    editedLabel(layout: LayoutTemplate): string {
      return this.relativeTime(layout.last_modified_on || layout.created_on) || '—';
    },
    relativeTime(dateStr?: string): string {
      if (!dateStr) return '';
      const then = new Date(dateStr).getTime();
      if (isNaN(then)) return '';
      const diff = Date.now() - then;
      const mins = Math.floor(diff / 60000);
      if (mins < 1) return this.$t('just_now');
      if (mins < 60) return mins === 1 ? this.$t('1_minute_ago') : this.$t('minutes_ago', { n: mins });
      const hrs = Math.floor(mins / 60);
      if (hrs < 24) return hrs === 1 ? this.$t('1_hour_ago') : this.$t('hours_ago', { n: hrs });
      const days = Math.floor(hrs / 24);
      if (days === 1) return this.$t('yesterday');
      if (days < 30) return this.$t('days_ago', { n: days });
      const months = Math.floor(days / 30);
      if (months < 12) return months === 1 ? this.$t('1_month_ago') : this.$t('months_ago', { n: months });
      const years = Math.floor(days / 365);
      return years === 1 ? this.$t('1_year_ago') : this.$t('years_ago', { n: years });
    },
    ruleCountLabel(layout: LayoutTemplate): string {
      const n = Number(layout.rule_count || 0);
      if (!n) return this.$t('not_targeted_by_rules');
      return n === 1
        ? this.$t('target_of_rule', { n })
        : this.$t('target_of_rules', { n });
    },
    editLayout(layout: LayoutTemplate) {
      // Opening a list item = opening that layout in the builder, carrying its
      // layout_type in the path (mirrors openFormBuilder in AdvanceSettings.vue).
      const url = formBuilderRouter.getFormBuilderRoute({
        doc_type_key: this.docType,
        layout_template_id: layout.id,
        sub_doc_type_key: layout.sub_doc_type_key || '',
        layout_type: this.routeLayoutType,
      });
      if (url) this.$router.push(url);
    },
    openNewLayoutDialog() {
      // A fresh dialog every time — no leftover title from a previous open.
      this.newLayoutTitle = '';
      this.showNewLayoutDialog = true;
    },
    async confirmNewLayout() {
      const title = this.newLayoutTitle.trim();
      if (!title || this.newLayoutBusy) return;
      try {
        this.newLayoutBusy = true;
        // Create an empty template up-front so the builder opens on a real id
        // (same destination edit/clone use). layout_type is always sent — the
        // panel is scoped to a single type. Blank layout_json; the builder
        // tolerates an empty layout and fills it in on first save.
        const response: any =
          await formBuilderApiService.createDocumentLayoutTemplate({
            doc_type_key: this.docType,
            sub_doc_type_key: '',
            title,
            layout_type: this.layoutType,
            layout_json: JSON.stringify({ layout: [] }),
          });
        if (response && response.success === false) {
          throw response;
        }
        const newId = response?.id || response?.data?.id;
        if (!newId) {
          throw { message: this.$t('could_not_create_layout') };
        }
        const url = formBuilderRouter.getFormBuilderRoute({
          doc_type_key: this.docType,
          layout_template_id: newId,
          sub_doc_type_key: '',
          layout_type: this.routeLayoutType,
        });
        this.showNewLayoutDialog = false;
        if (url) this.$router.push(url);
      } catch (err) {
        // Keep the dialog (and the typed title) so the user can retry.
        notify.error(ApiExceptions.getErrorMessage(err as dynamicObj));
        logError(err);
      } finally {
        this.newLayoutBusy = false;
      }
    },
    openCloneDialog(layout: LayoutTemplate) {
      this.pendingClone = layout;
      // Default title = the source name suffixed with "(Clone)".
      this.cloneTitle = (layout.title || this.$t('layout_default_title')) + ' ' + this.$t('clone_suffix');
      this.showCloneDialog = true;
    },
    async confirmClone() {
      const layout = this.pendingClone;
      const title = this.cloneTitle.trim();
      if (!layout || !title || this.cloneBusy) return;
      try {
        this.cloneBusy = true;
        this.busyId = layout.id;
        await formBuilderApiService.cloneDocumentLayoutTemplate(layout.id, {
          title,
          layout_type: layout.layout_type || LAYOUT_TYPE,
        });
        notify.success(this.$t('operation_sucessfull'));
        this.showCloneDialog = false;
        await this.loadLayouts();
      } catch (err) {
        notify.error(ApiExceptions.getErrorMessage(err as dynamicObj));
        logError(err);
      } finally {
        this.cloneBusy = false;
        this.busyId = '';
        this.pendingClone = null;
      }
    },
    confirmDelete(layout: LayoutTemplate) {
      this.pendingDelete = layout;
      this.showDeleteConfirm = true;
    },
    async deleteLayout() {
      const layout = this.pendingDelete;
      if (!layout) return;
      try {
        this.busyId = layout.id;
        const response: any =
          await formBuilderApiService.deleteDocumentLayoutTemplate(layout.id);
        if (response && response.success === false) {
          throw { message: response.message };
        }
        notify.success(this.$t('operation_sucessfull'));
        await this.loadLayouts();
      } catch (err) {
        notify.error(ApiExceptions.getErrorMessage(err as dynamicObj));
        logError(err);
      } finally {
        this.busyId = '';
        this.pendingDelete = null;
      }
    },
  },
});
</script>

