
<template>
  <!-- fb-sr-scope carries the --sr-* palette and the screen's shared primitives
       (badges / buttons / chips) from shadcn-theme.scss, so this panel and the
       separately-routed rule editor draw from one definition. -->
  <div class="fb-sr-scope">
    <!-- Explain banner -->
    <div class="fb-sr-explain">
      <Icon icon="mdi:information-outline" class="fb-sr-explain__icon" />
      <span>
        {{ $t('sr_explain_prefix') }} <b>{{ $t('sr_explain_bold_top_to_bottom') }}</b>
        {{ $t('sr_explain_mid') }} <b>{{ $t('sr_explain_bold_default_layout') }}</b>
        {{ $t('sr_explain_suffix') }}
      </span>
    </div>

    <!-- Toolbar -->
    <div class="fb-sr-toolbar">
      <div class="fb-sr-search">
        <Icon icon="mdi:magnify" class="fb-sr-search__icon" />
        <input
          v-model="searchQuery"
          type="text"
          :placeholder="$t('search_rules_placeholder')"
          :aria-label="$t('search_rules')"
        />
      </div>
      <div class="fb-sr-toolbar__spacer" />
      <button type="button" class="fb-sr-btn fb-sr-btn--primary" @click="openCreate">
        <Icon icon="mdi:plus" class="fb-sr-btn__icon" />
        {{ $t('new_rule') }}
      </button>
    </div>

    <!-- Loading skeletons -->
    <div v-if="isLoading" class="fb-sr-rules" aria-busy="true">
      <div v-for="n in 4" :key="n" class="fb-sr-rule fb-sr-rule--skeleton">
        <span class="fb-sr-sk fb-sr-sk--grip" />
        <span class="fb-sr-sk fb-sr-sk--prio" />
        <span class="fb-sr-sk fb-sr-sk--name" />
        <span class="fb-sr-sk fb-sr-sk--target" />
        <span class="fb-sr-sk fb-sr-sk--src" />
        <span class="fb-sr-sk fb-sr-sk--toggle" />
        <span />
      </div>
    </div>

    <!-- Empty state -->
    <div v-else-if="filteredRules.length === 0 && !defaultRule" class="fb-sr-empty">
      <Icon icon="mdi:sort-variant" class="fb-sr-empty__icon" />
      <p class="fb-sr-empty__title">
        {{ searchQuery.trim() ? $t('no_matching_rules') : $t('no_selection_rules_yet') }}
      </p>
      <p class="fb-sr-empty__hint">
        {{
          searchQuery.trim()
            ? $t('try_different_search')
            : $t('rules_empty_hint')
        }}
      </p>
      <button
        v-if="!searchQuery.trim()"
        type="button"
        class="fb-sr-btn fb-sr-btn--primary"
        @click="openCreate"
      >
        <Icon icon="mdi:plus" class="fb-sr-btn__icon" />
        {{ $t('new_rule') }}
      </button>
    </div>

    <!-- Rules table -->
    <template v-else>
      <div class="fb-sr-rulehead">
        <span />
        <span>{{ $t('priority') }}</span>
        <span>{{ $t('rule_and_conditions') }}</span>
        <span>{{ $t('target_layout') }}</span>
        <span>{{ $t('source') }}</span>
        <span>{{ $t('active') }}</span>
        <span />
      </div>

      <div class="fb-sr-rules">
        <draggable
          class="fb-sr-dragarea"
          :list="orderedRuleList"
          item-key="id"
          handle=".fb-sr-grip"
          :move="onDragMove"
          ghost-class="fb-sr-rule--ghost"
          @change="onReorder"
        >
          <div
            v-for="(rule, idx) in orderedRuleList"
            v-show="matchesSearch(rule)"
            :key="rule.id"
            class="fb-sr-rule"
            :class="{ 'fb-sr-rule--inactive': !rule.active }"
            @click="openEdit(rule)"
          >
            <span class="fb-sr-grip" aria-hidden="true" @click.stop>
              <img src="/icons/drag-grip.svg" class="fb-sr-grip__icon" alt="" />
            </span>
          <span class="fb-sr-prio tnum">
            {{ rule.priority }}
            <small>{{ idx === 0 ? $t('first') : '' }}</small>
          </span>
          <div class="fb-sr-rule__main">
            <div class="fb-sr-rname">
              {{ rule.name }}
              <span v-if="rule.key" class="fb-sr-k mono">{{ rule.key }}</span>
            </div>
            <div class="fb-sr-cond">
              <!-- One chip per TOP-LEVEL item of the rule's condition tree. A
                   nested sub-group becomes a single parenthesised chip joined by
                   its own all/any — flattening it here would claim a rule the
                   backend does not evaluate. -->
              <template v-for="(chip, ci) in conditionChips(rule.group)" :key="ci">
                <span v-if="ci > 0" class="fb-sr-lg">{{ rule.group.join === 'any' ? $t('or') : $t('and') }}</span>
                <span class="fb-sr-chip">
                  <template v-if="chip.text">{{ chip.text }}</template>
                  <template v-else>
                    {{ chip.field }} <span class="fb-sr-op">{{ chip.op }}</span> {{ chip.value }}
                  </template>
                </span>
              </template>
              <span v-if="!rule.group.conditions.length" class="fb-sr-lg fb-sr-lg--faint">
                {{ $t('no_conditions_short') }}
              </span>
            </div>
          </div>
          <div class="fb-sr-target">
            <span class="fb-sr-ti">
              <Icon icon="mdi:view-dashboard-outline" />
            </span>
            <div>
              <b>{{ rule.targetTitle }}</b>
              <span>{{ rule.targetType }}</span>
            </div>
          </div>
          <span class="fb-sr-badge" :class="sourceBadgeClass(rule.source)">
            <span v-if="rule.source === 'system'" class="fb-sr-dotstat" />
            {{ sourceLabel(rule.source) }}
          </span>
          <span class="fb-sr-toggle-cell" @click.stop>
            <f-toggle
              size="sm"
              :model-value="rule.active"
              :aria-label="rule.active ? $t('active') : $t('inactive')"
              @update:model-value="toggleActive(rule)"
            />
          </span>
          <RowActionsMenu
            :actions="ruleActions"
            :row="rule"
            @action="onRuleAction(rule, $event)"
          />
          </div>
        </draggable>

        <!-- Default / fallback row -->
        <div v-if="defaultRule" class="fb-sr-rule fb-sr-rule--default">
          <span class="fb-sr-grip fb-sr-grip--static" aria-hidden="true">
            <Icon icon="mdi:check" />
          </span>
          <span class="fb-sr-prio fb-sr-prio--faint">
            —<small>{{ $t('fallback') }}</small>
          </span>
          <div class="fb-sr-rule__main">
            <div class="fb-sr-rname">
              {{ defaultRule.name || $t('default_layout') }}
              <span class="fb-sr-badge fb-sr-badge--default">
                <span class="fb-sr-dotstat" />{{ $t('is_default') }}
              </span>
            </div>
            <div class="fb-sr-cond">
              <span class="fb-sr-lg fb-sr-lg--faint">{{ $t('used_when_no_rule_matches') }}</span>
            </div>
          </div>
          <div class="fb-sr-target">
            <span class="fb-sr-ti">
              <Icon icon="mdi:view-dashboard-outline" />
            </span>
            <div>
              <b>{{ defaultRule.targetTitle }}</b>
              <span>{{ defaultRule.targetType }}</span>
            </div>
          </div>
          <span class="fb-sr-badge" :class="sourceBadgeClass(defaultRule.source)">
            {{ sourceLabel(defaultRule.source) }}
          </span>
          <span class="fb-sr-always">{{ $t('always') }}</span>
          <button type="button" class="fb-sr-kebab" :aria-label="$t('more')" @click.stop>
            <Icon icon="mdi:dots-vertical" />
          </button>
        </div>
      </div>

      <div class="fb-sr-footnote">
        <Icon icon="mdi:information-outline" class="fb-sr-footnote__icon" />
        <span>
          {{ $t('sr_footnote_prefix') }} <b class="fb-sr-t-system">&nbsp;{{ $t('system_label') }}&nbsp;</b>
          {{ $t('sr_footnote_mid') }} <b class="fb-sr-t-warn">&nbsp;{{ $t('customized') }}&nbsp;</b>{{ $t('sr_footnote_suffix') }}
        </span>
      </div>
    </template>

    <ConfirmDialog
      v-model="showDeleteConfirm"
      :message="deleteMessage"
      :confirm-label="$t('delete')"
      :cancel-label="$t('cancel')"
      confirm-color="negative"
      @confirm="deleteRule"
    />
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { layout_types } from 'src/constants';
import type { dynamicObj } from 'src/pages/assets';
import { formBuilderApiService } from 'src/services';
import { ApiExceptions } from 'src/exceptions/index';
import { notify } from 'src/components/notifications/notify';
import FToggle from 'src/single-component/FellowToggle.vue';
import RowActionsMenu from 'src/components/Table/RowActionsMenu.vue';
import ConfirmDialog from 'src/supplier/pages/ConfirmDialog.vue';
import { VueDraggableNext } from 'vue-draggable-next';
import type { RowActionItem } from 'src/components/Table/types/table/unified-table';
import {
  buildFieldOptions,
  isBuilderGroup,
  loadHeaderFieldOptions,
  slugify,
  type BuilderGroup,
  type FieldOption,
} from 'src/pages/Settings/Components/CustomValidationRules/rule-builder-model';
// Parsing + display formatting are shared with the (separately routed) editor.
import { normalizeRule, OP_SYMBOLS } from './selection-rules.model';
import type {
  Condition,
  DisplayRule,
  EditingRule,
  RuleSource,
  TargetLayout,
} from './selection-rules.types';

const LAYOUT_TYPE = layout_types.field_validation;

// One rendered condition chip. A sub-group fills `text`; a leaf fills the three
// parts instead, so the operator keeps its own span in the template.
interface ConditionChip {
  text: string;
  field: string;
  op: string;
  value: string;
}

export default defineComponent({
  name: 'SelectionRulesPanel',
  components: { FToggle, RowActionsMenu, ConfirmDialog, draggable: VueDraggableNext },
  props: {
    docType: { type: String, default: '' },
    layoutType: { type: String, default: LAYOUT_TYPE },
    // Gates the (uncertain) rules fetch so it only fires once this tab is shown.
    active: { type: Boolean, default: false },
  },
  emits: ['update:count'],
  data() {
    return {
      rules: [] as DisplayRule[],
      // Non-default rules in display (priority) order — the draggable's source of
      // truth, mutated in place on drag then persisted via the reorder endpoint.
      orderedRuleList: [] as DisplayRule[],
      isLoading: false,
      searchQuery: '',
      // Document (doc.*) + header (header.*) condition field options, loaded once
      // per doc type and handed to the drawer as a prop (so they're ready before
      // the editor opens — no lazy-load race in the picker).
      fieldOptions: [] as FieldOption[],
      fieldsLoaded: false,
      // Layout templates for the current doc type + layout type — the drawer's
      // "Target layout" picker options. Loaded alongside the rules so the list
      // is ready before the editor opens.
      layouts: [] as TargetLayout[],
      showDeleteConfirm: false,
      pendingDelete: null as DisplayRule | null,
      // Same kebab menu the validation-rules table uses (Edit + Duplicate +
      // Delete-in-red).
      ruleActions: [
        { key: 'edit', label: 'edit', icon: 'edit' },
        { key: 'duplicate', label: 'duplicate', icon: 'content_copy' },
        { key: 'delete', label: 'delete', icon: 'delete', color: 'negative', separator: true },
      ] as RowActionItem[],
    };
  },
  computed: {
    deleteMessage(): string {
      const name = this.pendingDelete?.name || this.$t('this_rule');
      return this.$t('delete_item_confirm', { name });
    },
    defaultRule(): DisplayRule | null {
      return this.rules.find((r) => r.isDefault) || null;
    },
    isSearching(): boolean {
      return this.searchQuery.trim() !== '';
    },
    filteredRules(): DisplayRule[] {
      return this.orderedRuleList.filter((r: DisplayRule) => this.matchesSearch(r));
    },
  },
  watch: {
    active(val: boolean) {
      if (val) this.loadRules();
    },
    docType() {
      // Field options are doc-type-specific — force a reload for the new type.
      this.fieldsLoaded = false;
      if (this.active) this.loadRules();
    },
    layoutType() {
      if (this.active) this.loadRules();
    },
  },
  mounted() {
    if (this.active) this.loadRules();
  },
  methods: {
    // Load the condition field picker options (doc.* + header.*) once per doc
    // type. Fired alongside loadRules so the list is ready before the editor
    // drawer can be opened — mirrors how RuleBuilder feeds ConditionGroup.
    async loadFieldOptions() {
      if (this.fieldsLoaded || !this.docType) return;
      try {
        const headerFields = await loadHeaderFieldOptions(this.docType);
        this.fieldOptions = buildFieldOptions('header', headerFields, []);
        this.fieldsLoaded = true;
      } catch (err) {
        // Non-fatal: the drawer still opens, the picker just has no suggestions.
        logError(err);
      }
    },
    // Load the layout templates for the current doc type + layout type so the
    // drawer's "Target layout" picker has options. Same endpoint LayoutsPanel
    // uses; non-fatal on failure (the drawer just shows an empty picker).
    async loadLayouts() {
      if (!this.docType) return;
      try {
        const response: any = await formBuilderApiService.getAllLayoutTemplates({
          layout_type: this.layoutType,
          doc_type: this.docType,
          // scope 'all' includes the default-org layouts. Without it a seeded
          // rule targeting a system default has no option to match, and its
          // target picker renders as though nothing were selected.
          scope: 'all',
        });
        this.layouts = Array.isArray(response)
          ? response
          : Array.isArray(response?.data)
            ? response.data
            : [];
      } catch (err) {
        logError(err);
      }
    },
    async loadRules() {
      if (!this.docType) return;
      this.loadFieldOptions();
      this.loadLayouts();
      try {
        this.isLoading = true;
        const response: any = await formBuilderApiService.getLayoutSelectionRules({
          doc_type_key: this.docType,
          layout_type: this.layoutType,
        });
        // Tolerate a bare array, a { data: [...] } envelope, or { rules: [...] }.
        const list = Array.isArray(response)
          ? response
          : Array.isArray(response?.data)
            ? response.data
            : Array.isArray(response?.rules)
              ? response.rules
              : [];
        const ctx = {
          layoutType: this.layoutType,
          untitledLabel: this.$t('untitled_rule'),
        };
        this.rules = list.map((r: any, i: number) => normalizeRule(r, i, ctx));
        this.orderedRuleList = this.rules
          .filter((r: DisplayRule) => !r.isDefault)
          .sort(
            (a: DisplayRule, b: DisplayRule) =>
              Number(a.priority) - Number(b.priority),
          );
        this.$emit('update:count', this.rules.length);
      } catch (err) {
        notify.error(ApiExceptions.getErrorMessage(err as dynamicObj));
        logError(err);
      } finally {
        this.isLoading = false;
      }
    },
    // ---- Display-only formatting (row summary chips) --------------------
    // One chip per top-level tree item. A leaf keeps its three parts so the
    // operator can carry its own styling; a sub-group collapses to a single
    // parenthesised `text` chip (see groupChipText).
    conditionChips(group: BuilderGroup): ConditionChip[] {
      return group.conditions.map((item) =>
        isBuilderGroup(item)
          ? { text: this.groupChipText(item), field: '', op: '', value: '' }
          : {
              text: '',
              field: item.field,
              op: this.condOpSymbol(item),
              value: this.condDisplayValue(item),
            },
      );
    },
    // A sub-group as one chip: its items joined by its OWN all/any, nesting as
    // deep as the tree goes.
    groupChipText(group: BuilderGroup): string {
      const joiner = group.join === 'any' ? this.$t('or') : this.$t('and');
      const parts = group.conditions.map((item) =>
        isBuilderGroup(item)
          ? this.groupChipText(item)
          : `${item.field} ${this.condOpSymbol(item)} ${this.condDisplayValue(item)}`.trim(),
      );
      return `(${parts.join(` ${joiner} `)})`;
    },
    // The stored condition is raw; these turn it into the mockup's
    // `field = "DE"` style without mutating the model.
    condOpSymbol(c: Condition): string {
      const sym = OP_SYMBOLS[c.op] || c.op;
      return c.negate ? `not ${sym}` : sym;
    },
    condDisplayValue(c: Condition): string {
      if (c.op === 'not_empty') return '';
      if (c.op === 'in') return `[${c.value}]`;
      return this.formatValue(c.value);
    },
    // Quote string values to match the mockup's `= "DE"` style; leave numbers bare.
    formatValue(raw: any): string {
      if (raw === undefined || raw === null) return '';
      if (typeof raw === 'string' && raw !== '' && isNaN(Number(raw))) {
        return `"${raw}"`;
      }
      return String(raw);
    },
    sourceLabel(source: RuleSource): string {
      if (source === 'system') return this.$t('system_label');
      if (source === 'customized') return this.$t('customized');
      return this.$t('custom');
    },
    sourceBadgeClass(source: RuleSource): string {
      if (source === 'system') return 'fb-sr-badge--system';
      if (source === 'customized') return 'fb-sr-badge--customized';
      return 'fb-sr-badge--custom';
    },
    async toggleActive(rule: DisplayRule) {
      // Optimistic flip, then persist via the toggle endpoint. Roll back on failure
      // so the switch always reflects the real server state.
      const next = !rule.active;
      rule.active = next;
      try {
        await formBuilderApiService.toggleLayoutSelectionRule(rule.id, next);
      } catch (err) {
        rule.active = !next;
        notify.error(ApiExceptions.getErrorMessage(err as dynamicObj));
        logError(err);
      }
    },
    matchesSearch(rule: DisplayRule): boolean {
      const q = this.searchQuery.trim().toLowerCase();
      if (!q) return true;
      const conds = rule.conditions
        .map((c) => `${c.field} ${c.value}`)
        .join(' ');
      const haystack =
        `${rule.name} ${rule.key} ${rule.targetTitle} ${conds}`.toLowerCase();
      return haystack.includes(q);
    },
    // Block drops while a search filter is active (rows are hidden then, so an index
    // swap would be meaningless). Returning false cancels the move. Passed via the
    // declared `move` prop so it never leaks a `disabled` attribute onto the DOM.
    onDragMove(): boolean {
      return !this.isSearching;
    },
    // Drag reorder finished — draggable has already reordered orderedRuleList in
    // place. Renumber the priority labels to stay ascending in the new order, then
    // persist the new rule_key sequence. Revert from the server on failure.
    async onReorder() {
      const ruleKeys = this.orderedRuleList
        .map((r: DisplayRule) => r.rule_key || r.key)
        .filter(Boolean);
      const priorities = this.orderedRuleList
        .map((r: DisplayRule) => Number(r.priority))
        .sort((a: number, b: number) => a - b);
      this.orderedRuleList.forEach((r: DisplayRule, i: number) => {
        if (priorities[i] !== undefined) r.priority = priorities[i];
      });
      try {
        await formBuilderApiService.reorderLayoutSelectionRules(
          this.docType,
          this.layoutType,
          ruleKeys,
        );
      } catch (err) {
        notify.error(ApiExceptions.getErrorMessage(err as dynamicObj));
        logError(err);
        await this.loadRules();
      }
    },
    // The editor is its own route. Create goes to /new; edit hands the row over
    // via router state so the editor prefills without a round-trip (it falls
    // back to re-fetching the list on a deep link / refresh).
    editorPath(segment: string): string {
      return `/settings/doc-type-settings/${this.docType}/layouts/selection-rules/${segment}`;
    },
    openCreate() {
      this.$router.push({
        path: this.editorPath('new'),
        query: { layout_type: this.layoutType },
      });
    },
    openEdit(rule: DisplayRule) {
      // Clone into router state so the editor's edits never touch the list row.
      // `conditions` / `match` are this list's flattened display mirror — the
      // editor works on the `group` tree, so only that is handed over.
      const { conditions, match, ...carried } = rule;
      const editing: EditingRule = { ...carried, isNew: false };
      this.$router.push({
        path: this.editorPath(rule.id),
        query: { layout_type: this.layoutType },
        state: { rule: JSON.parse(JSON.stringify(editing)) },
      });
    },
    onRuleAction(rule: DisplayRule, key: string) {
      if (key === 'edit') this.openEdit(rule);
      else if (key === 'duplicate') this.duplicateRule(rule);
      else if (key === 'delete') this.confirmDelete(rule);
    },
    // Duplicate a rule: the backend clones the full definition off the source
    // row, so only the new identity is sent — " - Copy" appended to the name
    // plus a matching fresh rule_key (the same slug the server would derive).
    // Works for a system rule too; the copy is created as a custom one.
    async duplicateRule(rule: DisplayRule) {
      if (!rule || !rule.id) return;
      const display_name = `${rule.name} - Copy`;
      try {
        const response: any = await formBuilderApiService.cloneLayoutSelectionRule(
          rule.id,
          { rule_key: slugify(display_name), display_name },
        );
        if (response && response.success === false) {
          throw { message: response.message };
        }
        notify.success(this.$t('operation_sucessfull'));
        await this.loadRules();
      } catch (err) {
        notify.error(ApiExceptions.getErrorMessage(err as dynamicObj));
        logError(err);
      }
    },
    confirmDelete(rule: DisplayRule) {
      this.pendingDelete = rule;
      this.showDeleteConfirm = true;
    },
    async deleteRule() {
      const rule = this.pendingDelete;
      if (!rule) return;
      try {
        const response: any =
          await formBuilderApiService.deleteLayoutSelectionRule(rule.id);
        if (response && response.success === false) {
          throw { message: response.message };
        }
        notify.success(this.$t('operation_sucessfull'));
        await this.loadRules();
      } catch (err) {
        notify.error(ApiExceptions.getErrorMessage(err as dynamicObj));
        logError(err);
      } finally {
        this.pendingDelete = null;
      }
    },
  },
});
</script>

